const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

/** Thrown for any input that fails to parse; carries the line number, or
 * `null` when the failure has none (there were no candidates at all). */
export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

function fail(line, message) {
  throw new ParseError(message, line)
}

/**
 * @param {string} input the raw standard input text
 * @returns {{ candidates: string[], ballots: { count: number, names: string[] }[] }}
 */
export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const candidates = []
  const candidateSet = new Set()
  const ballots = []
  let declared = false

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (declared) fail(lineNumber, 'candidates must be declared once, before any ballot')
      if (tokens.length < 2) fail(lineNumber, 'expected candidates <name>...')
      for (const name of tokens.slice(1)) {
        if (!NAME_RE.test(name)) fail(lineNumber, `invalid candidate name ${name}`)
        if (candidateSet.has(name)) fail(lineNumber, `candidate ${name} is declared twice`)
        candidateSet.add(name)
        candidates.push(name)
      }
      declared = true
    } else if (directive === 'ballot') {
      if (!declared) fail(lineNumber, 'candidates must be declared once, before any ballot')
      if (tokens.length < 3) fail(lineNumber, 'expected ballot <count> <candidate>...')
      const countText = tokens[1]
      if (!COUNT_RE.test(countText)) fail(lineNumber, 'count must be a positive integer')
      const count = Number(countText)
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) fail(lineNumber, `unknown candidate ${name}`)
        if (seen.has(name)) fail(lineNumber, `candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      fail(lineNumber, `unknown directive ${directive}`)
    }
  }

  if (!declared) fail(null, 'no candidates')

  return { candidates, ballots }
}
"}

