{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T235858Z/cell-HwoveB/src/rounds.js","content":"/**
 * Runs the instant-runoff count described by the specification: every round
 * each ballot counts for its first still-continuing candidate, a majority of
 * the active total wins, and otherwise the round's lowest-scoring candidate
 * is eliminated, breaking ties by comparing earlier rounds and finally by
 * name.
 *
 * @param {string[]} candidates the declared candidate names, in declaration order
 * @param {{ count: number, names: string[] }[]} ballots
 * @returns {{ rounds: { votes: [string, number][], exhausted: number, eliminated: string|null }[], winner: string|null }}
 *   `votes` lists every candidate continuing during that round, in
 *   descending vote order (ascending name on ties), each entry named for
 *   printing.
 */
export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const history = [] // history[i] is a Map<name, votes> for round i + 1
  const rounds = []
  let winner = null

  while (true) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) exhausted += ballot.count
      else votes.set(choice, votes.get(choice) + ballot.count)
    }

    history.push(votes)
    const activeTotal = [...votes.values()].reduce((a, b) => a + b, 0)

    const ordered = [...votes.entries()].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1))

    if (activeTotal === 0) {
      rounds.push({ votes: ordered, exhausted, eliminated: null })
      break
    }

    const [leadName, leadVotes] = ordered[0]
    if (leadVotes * 2 > activeTotal) {
      winner = leadName
      rounds.push({ votes: ordered, exhausted, eliminated: null })
      break
    }

    const fewest = Math.min(...votes.values())
    const tied = [...continuing].filter((name) => votes.get(name) === fewest)
    const eliminated = tied.length === 1 ? tied[0] : breakTie(tied, history)

    rounds.push({ votes: ordered, exhausted, eliminated })
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}

/**
 * Resolves an elimination tie by comparing the tied candidates' counts round
 * by round from the first round, narrowing to whichever had fewest whenever
 * a round distinguishes them and restarting the comparison from the first
 * round among the survivors, until one candidate remains or every round
 * agrees; in the latter case the name that sorts last by code point loses.
 *
 * @param {string[]} tied candidate names tied for fewest votes this round
 * @param {Map<string, number>[]} history each already-counted round's votes, this one included
 * @returns {string} the candidate to eliminate
 */
function breakTie(tied, history) {
  let remaining = tied
  for (;;) {
    let narrowed = null
    for (const roundVotes of history) {
      const counts = remaining.map((name) => roundVotes.get(name))
      if (counts.some((c) => c !== counts[0])) {
        const min = Math.min(...counts)
        narrowed = remaining.filter((name) => roundVotes.get(name) === min)
        break
      }
    }
    if (narrowed === null) break
    remaining = narrowed
    if (remaining.length === 1) return remaining[0]
  }
  return remaining.reduce((worst, name) => (name > worst ? name : worst))
}
"}

